            cipher.init(Cipher.ENCRYPT_MODE, aesKey(), new IvParameterSpec(syntheticIv));
            byte[] encrypted = cipher.doFinal(plain);

            byte[] out = new byte[syntheticIv.length + encrypted.length];
            System.arraycopy(syntheticIv, 0, out, 0, syntheticIv.length);
            System.arraycopy(encrypted, 0, out, syntheticIv.length, encrypted.length);
            return Base64.getEncoder().encodeToString(out);
        } catch (Exception e) {
