     * @return 복호화된 원본 문자열
     */
    public String deterministicDecrypt(String encryptedText) {
        if (encryptedText == null || encryptedText.isEmpty()) {
            return encryptedText;
        }

        try {
            byte[] decoded = Base64.getDecoder().decode(encryptedText);
            byte[] ivBytes = new byte[16];
            System.arraycopy(decoded, 0, ivBytes, 0, 16);
            byte[] body = new byte[decoded.length - 16];
            System.arraycopy(decoded, 16, body, 0, body.length);

            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.DECRYPT_MODE, aesKey(), new IvParameterSpec(ivBytes));
            return new String(cipher.doFinal(body), StandardCharsets.UTF_8);
        } catch (Exception e) {
            log.error("결정적 복호화 중 오류 발생: {}", e.getMessage(), e);
            throw new RuntimeException("결정적 복호화 처리 중 오류가 발생했습니다", e);
        }
    }

